namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A", "Warehouse 1", new DateTime(2026, 6, 15)),
            new(2, "Conveyor Belt B", "Warehouse 2", new DateTime(2026, 5, 20)),
            new(3, "CNC Lathe", "Machine Shop", new DateTime(2026, 4, 10)),
            new(4, "Hydraulic Press", "Assembly Floor", new DateTime(2026, 6, 28)),
            new(5, "Air Compressor", "Utility Room", new DateTime(2026, 3, 5)),
            new(6, "Pallet Jack C", "Warehouse 1", new DateTime(2026, 7, 1)),
            new(7, "Welding Station", "Fabrication Bay", new DateTime(2026, 2, 18)),
            new(8, "Drill Press", "Machine Shop", new DateTime(2026, 6, 3)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@implements IDisposable
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            // First render (prerender): fetch from service
            items = await EquipmentService.GetEquipmentAsync();
        }
        else
        {
            // Interactive render: use persisted data — no second fetch
            items = restored;
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

